	/** M12a: rot pulsierender Rahmen des Suggestion-Felds bei aktivem Dump-Alert. */
	private javax.swing.Timer dumpPulseTimer;
	/**
	 * Alle dauerhaft laufenden Timer dieses Panels.
	 *
	 * Sie wurden frueher nur gestartet und nie gestoppt. Da shutDown() das Panel
	 * verwirft, lief bei jedem Plugin-Neustart ein weiterer Satz Timer fuer immer
	 * weiter und griff ins Leere - im Client-Log als NullPointerException aus
	 * refreshStats() sichtbar, weil das Plugin sein Panel-Feld da schon genullt hat.
	 * Der Sekundentakt-Timer summierte sich dabei ueber jeden Neustart
	 * (Fund 09.09.2026 im Client-Log).
	 */
	private final java.util.List<javax.swing.Timer> laufendeTimer = new java.util.ArrayList<>();

	/** Alle Timer anhalten - vom Plugin beim Herunterfahren gerufen. */
	void stoppeTimer()
	{
		for (javax.swing.Timer t : laufendeTimer)
		{
			t.stop();
		}
		laufendeTimer.clear();
		stopDumpPulse();
	}

	/** Timer starten UND merken, damit er beim Herunterfahren wieder aufhoert. */
	private void starteTimer(int ms, java.awt.event.ActionListener aktion)
	{
		javax.swing.Timer t = new javax.swing.Timer(ms, aktion);
		laufendeTimer.add(t);
		t.start();
	}

	private void startDumpPulse()
	{
		if (dumpPulseTimer != null && dumpPulseTimer.isRunning())
		{
			return;
		}
		final long start = System.currentTimeMillis();
		dumpPulseTimer = new javax.swing.Timer(80, e -> {
			double t = ((System.currentTimeMillis() - start) % 900) / 900.0;
			float p = (float) (0.5 - 0.5 * Math.cos(2 * Math.PI * t)); // 0..1
			// Rahmen: dunkles Pink <-> knalliges Pink (2026-07-22, vorher rot).
			Color pink = new Color(255, 64, 210);
			Color dim = new Color(92, 26, 76);
			Color line = lerp(dim, pink, p);
			// Hintergrund pulsiert dezent mit (dunkel genug, dass der Text lesbar bleibt).
			Color bgDark = new Color(46, 14, 38);
			Color bgBright = new Color(92, 28, 76);
			suggestionRow.setBackground(lerp(bgDark, bgBright, p));
			suggestionRow.setBorder(BorderFactory.createCompoundBorder(
				BorderFactory.createLineBorder(line, 2, true),
				BorderFactory.createEmptyBorder(3, 6, 5, 6)));
		});
		dumpPulseTimer.start();
	}

	private void stopDumpPulse()
	{
		if (dumpPulseTimer != null)
		{
			dumpPulseTimer.stop();
			dumpPulseTimer = null;
		}
	}

	private static Color lerp(Color a, Color b, float p)
	{
		return new Color(
			(int) (a.getRed() + (b.getRed() - a.getRed()) * p),
			(int) (a.getGreen() + (b.getGreen() - a.getGreen()) * p),
			(int) (a.getBlue() + (b.getBlue() - a.getBlue()) * p));
	}

