	private void openFeedbackDialog()
	{
		javax.swing.JComboBox<String> cat = new javax.swing.JComboBox<>(new String[]{"Feedback / idea", "Bug report"});
		javax.swing.JTextArea text = new javax.swing.JTextArea(8, 28);
