package de.rsflipper;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import de.rsflipper.model.FillEvent;
import java.io.File;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

/**
 * Durable Outbox für Fill-Events (SPEC §4.5/§12.6): Fills werden lokal persistiert
 * und erst nach Server-Bestätigung (ackedFillIds) entfernt. Garantiert, dass bei
 * Verbindungsabbruch oder Client-Neustart kein Trade verloren geht und keiner doppelt
 * zählt (Server dedupt zusätzlich per id) — Basis für korrektes Cross-Device-Tracking.
 */
@Slf4j
public class FillOutbox
{
	private static final Type FILE_TYPE = new TypeToken<LinkedHashMap<String, FillEvent>>() {}.getType();

	private final Gson gson;
	private final Map<String, FillEvent> pending = new LinkedHashMap<>();
	private long accountHash;

	public FillOutbox(Gson gson)
	{
		this.gson = gson;
	}

	public synchronized void load(long accountHash)
	{
		this.accountHash = accountHash;
		pending.clear();
		File f = file();
		if (!f.exists())
		{
			return;
		}
		try
		{
			String json = new String(Files.readAllBytes(f.toPath()), StandardCharsets.UTF_8);
			Map<String, FillEvent> loaded = gson.fromJson(json, FILE_TYPE);
			if (loaded != null)
			{
				pending.putAll(loaded);
			}
			log.debug("Outbox geladen: {} ausstehende Fills", pending.size());
		}
		catch (Exception e)
		{
			log.warn("Outbox nicht lesbar — starte leer", e);
		}
	}

	public synchronized void add(FillEvent fill)
	{
		pending.put(fill.getId(), fill);
		persist();
	}

	public synchronized List<FillEvent> snapshot()
	{
		return new ArrayList<>(pending.values());
	}

	/** Vom Server bestätigte Fills entfernen. */
	public synchronized void ack(List<String> ids)
	{
		boolean changed = false;
		for (String id : ids)
		{
			if (pending.remove(id) != null)
			{
				changed = true;
			}
		}
		if (changed)
		{
			persist();
		}
	}

	private void persist()
	{
		File f = file();
		try
		{
			//noinspection ResultOfMethodCallIgnored
			f.getParentFile().mkdirs();
			Files.write(f.toPath(), gson.toJson(pending, FILE_TYPE).getBytes(StandardCharsets.UTF_8));
		}
		catch (Exception e)
		{
			log.warn("Outbox konnte nicht gespeichert werden", e);
		}
	}

	private File file()
	{
		return new File(new File(RuneLite.RUNELITE_DIR, "rs-flipper"), "outbox_" + accountHash + ".json");
	}
}

package de.rsflipper.api;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * M9 (SPEC §12.1): Login gegen die RS-Flipper-API. Access-Token (1h) + Refresh-Token
 * (30 Tage) werden über den ConfigManager persistiert (überleben Client-Neustarts,
 * versteckte Keys ohne @ConfigItem). Bei 401 versucht der Plugin-Sync einen Refresh.
 */
@Slf4j
@Singleton
public class AuthService
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final String GROUP = "rsflipper";
	private static final String KEY_ACCESS = "authAccessToken";
	private static final String KEY_REFRESH = "authRefreshToken";
	private static final String KEY_EMAIL = "authEmail";

	/** Device-Flow: 2,5 s zwischen zwei Abfragen, hoechstens 4 Minuten insgesamt. */
	private static final long POLL_DELAY_MS = 2500;
	private static final int POLL_MAX_TRIES = 96;

	private final OkHttpClient http;
	private final Gson gson;
	private final ConfigManager configManager;
	private final ScheduledExecutorService scheduler;
	private volatile boolean refreshing = false;
	/** Laufender Device-Flow, damit ein zweiter Login-Versuch den alten ablöst. */
	private volatile ScheduledFuture<?> discordPoll;
	/**
	 * Generationszaehler des Device-Flows. cancel() auf dem Future allein genuegt NICHT:
	 * Ist gerade eine HTTP-Abfrage unterwegs, wuerde deren Callback den naechsten Versuch
	 * trotzdem einplanen. Jeder Lauf merkt sich seine Generation und bricht ab, sobald
	 * eine neuere existiert.
	 */
	private volatile long discordPollGen;

	@Inject
	public AuthService(OkHttpClient http, Gson gson, ConfigManager configManager, ScheduledExecutorService scheduler)
	{
		this.http = http;
		this.gson = gson;
		this.configManager = configManager;
		this.scheduler = scheduler;
	}

	public boolean isLoggedIn()
	{
		return accessToken() != null;
	}

	public String email()
	{
		return configManager.getConfiguration(GROUP, KEY_EMAIL);
	}

	public String accessToken()
	{
		String t = configManager.getConfiguration(GROUP, KEY_ACCESS);
		return t == null || t.isEmpty() ? null : t;
	}

	private String refreshToken()
	{
		String t = configManager.getConfiguration(GROUP, KEY_REFRESH);
		return t == null || t.isEmpty() ? null : t;
	}

	/** Authorization-Header-Wert oder null (Dev ohne Login). */
	public String bearer()
	{
		String t = accessToken();
		return t == null ? null : "Bearer " + t;
	}

	/**
	 * Wird gerufen, wenn der Anmeldezustand von aussen wegfaellt — also NICHT durch
	 * einen Klick, sondern weil der Refresh-Token abgelaufen/widerrufen ist. Ohne
	 * diesen Rueckruf blieb die Login-Box auf dem alten Stand stehen: Sie zeigte
	 * weiter "Log out", versteckte E-Mail-, Passwort- und Discord-Feld, und der
	 * Knopf war tot (er prueft isLoggedIn() und landet im Login-Zweig mit leeren
	 * Feldern). Der User kam ohne Client-Neustart nicht mehr heraus.
	 * (2026-08-27, Fund kurz nach der Aufnahme in den Plugin Hub.)
	 */
	private volatile Runnable onLoggedOut;

	public void setOnLoggedOut(Runnable r)
	{
		this.onLoggedOut = r;
	}

	public void logout()
	{
		configManager.unsetConfiguration(GROUP, KEY_ACCESS);
		configManager.unsetConfiguration(GROUP, KEY_REFRESH);
		configManager.unsetConfiguration(GROUP, KEY_EMAIL);
		Runnable r = onLoggedOut;
		if (r != null)
		{
			r.run();
		}
	}

	public void login(String serverUrl, String email, String password, Consumer<String> onDone)
	{
		JsonObject body = new JsonObject();
		body.addProperty("email", email);
		body.addProperty("password", password);
		Request request = new Request.Builder()
			.url(serverUrl + "/auth/login")
			.post(RequestBody.create(JSON, body.toString()))
			.build();
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				onDone.accept("Server unreachable");
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				try (Response r = response)
				{
					JsonObject d = gson.fromJson(r.body() != null ? r.body().string() : "{}", JsonObject.class);
					if (!r.isSuccessful())
					{
						onDone.accept(d != null && d.has("error") ? d.get("error").getAsString() : "Login failed (" + r.code() + ")");
						return;
					}
					configManager.setConfiguration(GROUP, KEY_ACCESS, d.get("accessToken").getAsString());
					configManager.setConfiguration(GROUP, KEY_REFRESH, d.get("refreshToken").getAsString());
					configManager.setConfiguration(GROUP, KEY_EMAIL, email);
					onDone.accept(null); // null = Erfolg
				}
				catch (Exception e)
				{
					onDone.accept("Login response unreadable");
				}
			}
		});
	}

	/** Phase 6: Login per Discord (Device-Flow). Oeffnet den Browser mit einem
	 *  Einmal-Code; der Server hinterlegt die Tokens nach dem OAuth-Callback und
	 *  wir pollen sie hier ab (2,5s-Takt, max. 4 Minuten). */
	public void loginWithDiscord(String serverUrl, Consumer<String> onDone)
	{
		byte[] rnd = new byte[16];
		new java.security.SecureRandom().nextBytes(rnd);
		StringBuilder sb = new StringBuilder();
		for (byte b : rnd)
		{
			sb.append(String.format("%02x", b));
		}
		String code = sb.toString();
		net.runelite.client.util.LinkBrowser.browse(serverUrl + "/auth/discord/start?device=" + code);
		cancelDiscordPoll();
		schedulePoll(serverUrl, code, 1, onDone, ++discordPollGen);
	}

	/** Laufenden Device-Flow beenden (neuer Login-Versuch oder Plugin-Shutdown). */
	public void cancelDiscordPoll()
	{
		discordPollGen++; // laufende Callbacks entwerten
		ScheduledFuture<?> laufend = discordPoll;
		if (laufend != null)
		{
			laufend.cancel(false);
			discordPoll = null;
		}
	}

	/**
	 * Eine einzelne Abfrage des Device-Flows einplanen.
	 *
	 * Bewusst OHNE eigenen Thread, ohne Thread.sleep und ohne Interrupt (Auflage des
	 * Plugin-Hub-Reviews): Der Takt kommt vom ScheduledExecutorService von RuneLite,
	 * die HTTP-Abfrage laeuft asynchron ueber OkHttp. Der jeweils naechste Versuch
	 * wird erst aus der Antwort heraus eingeplant — so blockiert nie ein Thread, und
	 * es gibt nichts zu unterbrechen. Abgebrochen wird ueber cancel() des Futures.
	 */
	private void schedulePoll(String serverUrl, String code, int versuch, Consumer<String> onDone, long gen)
	{
		if (gen != discordPollGen)
		{
			return; // abgebrochen oder von einem neueren Login-Versuch abgeloest
		}
		if (versuch > POLL_MAX_TRIES)
		{
			discordPoll = null;
			onDone.accept("Discord login timed out - please try again");
			return;
		}
		discordPoll = scheduler.schedule(() -> {
			if (gen != discordPollGen)
			{
				return;
			}
			JsonObject body = new JsonObject();
			body.addProperty("code", code);
			Request request = new Request.Builder()
				.url(serverUrl + "/auth/device/poll")
				.post(RequestBody.create(JSON, body.toString()))
				.build();
			http.newCall(request).enqueue(new Callback()
			{
				@Override
				public void onFailure(Call call, IOException e)
				{
					// Netz-Huckel: einfach weiterpollen
					schedulePoll(serverUrl, code, versuch + 1, onDone, gen);
				}

				@Override
				public void onResponse(Call call, Response response)
				{
					try (Response r = response)
					{
						if (gen != discordPollGen)
						{
							return;
						}
						if (r.isSuccessful() && r.body() != null)
						{
							JsonObject d = gson.fromJson(r.body().string(), JsonObject.class);
							if (d != null && d.has("ready") && d.get("ready").getAsBoolean())
							{
								configManager.setConfiguration(GROUP, KEY_ACCESS, d.get("accessToken").getAsString());
								configManager.setConfiguration(GROUP, KEY_REFRESH, d.get("refreshToken").getAsString());
								configManager.setConfiguration(GROUP, KEY_EMAIL, d.get("email").getAsString());
								discordPoll = null;
								onDone.accept(null);
								return;
							}
						}
					}
					catch (Exception ignored)
					{
						// Unlesbare Antwort wie einen Netz-Huckel behandeln
					}
					schedulePoll(serverUrl, code, versuch + 1, onDone, gen);
				}
			});
		}, POLL_DELAY_MS, TimeUnit.MILLISECONDS);
	}

	/**
	 * Access-Token per Refresh-Token erneuern (max. 1 Versuch parallel).
	 *
	 * onErneuert wird NUR bei Erfolg aufgerufen. Ohne diesen Rueckruf blieb nach dem
	 * Erneuern alles liegen, bis der normale Heartbeat feuerte — bei ruhiger Markthalle
	 * bis zu 50 Ticks (~30 s), in denen das Panel "Renewing session ..." zeigte, obwohl
	 * das neue Token laengst da war (2026-07-29).
	 */
	public void tryRefresh(String serverUrl)
	{
		tryRefresh(serverUrl, null);
	}

	public void tryRefresh(String serverUrl, Runnable onErneuert)
	{
		String refresh = refreshToken();
		if (refresh == null || refreshing)
		{
			return;
		}
		refreshing = true;
		JsonObject body = new JsonObject();
		body.addProperty("refreshToken", refresh);
		Request request = new Request.Builder()
			.url(serverUrl + "/auth/refresh")
			.post(RequestBody.create(JSON, body.toString()))
			.build();
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				refreshing = false;
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				try (Response r = response)
				{
					if (r.isSuccessful() && r.body() != null)
					{
						JsonObject d = gson.fromJson(r.body().string(), JsonObject.class);
						configManager.setConfiguration(GROUP, KEY_ACCESS, d.get("accessToken").getAsString());
						log.debug("Access-Token erneuert");
					}
					else if (r.code() == 401)
					{
						// Refresh-Token abgelaufen/widerrufen -> sauber ausloggen.
						logout();
					}
				}
				catch (Exception ignored)
				{
				}
				finally
				{
					refreshing = false;
				}
			}
		});
	}
}

package de.rsflipper.api;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * HTTP-Schicht zum RS-Flipper-Server (SPEC §11): AccountStatus hin, Suggestion zurück.
 * Async über OkHttp — blockiert nie den ClientThread. Auth (JWT) folgt in M9.
 */
@Slf4j
@Singleton
public class ApiClient
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

	private final OkHttpClient http;
	private final Gson gson;
	private final AuthService auth;

	@Inject
	public ApiClient(OkHttpClient http, Gson gson, AuthService auth)
	{
		this.http = http;
		this.gson = gson;
		this.auth = auth;
	}

	/** M9: Authorization-Header anhaengen, wenn eingeloggt. */
	private Request.Builder authed(Request.Builder b)
	{
		String bearer = auth.bearer();
		if (bearer != null)
		{
			b.header("Authorization", bearer);
		}
		return b;
	}

	/** §4.6: optimale Order-Preise für manuelle Trades (Quote-Hilfe). */
	public void getQuote(String serverUrl, int itemId, Consumer<JsonObject> onSuccess)
	{
		Request request = authed(new Request.Builder())
			.url(serverUrl + "/prices/quote/" + itemId)
			.get()
			.build();
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				try (Response r = response)
				{
					if (r.isSuccessful() && r.body() != null)
					{
						onSuccess.accept(gson.fromJson(r.body().string(), JsonObject.class));
					}
				}
				catch (Exception ignored)
				{
				}
			}
		});
	}

	/** Phase 3: Praeferenzen lesen (Sync ueber Geraete). */
	public void getPreferences(String serverUrl, Consumer<JsonObject> onSuccess)
	{
		Request request = authed(new Request.Builder())
			.url(serverUrl + "/me/preferences")
			.get()
			.build();
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				try (Response r = response)
				{
					if (r.isSuccessful() && r.body() != null)
					{
						onSuccess.accept(gson.fromJson(r.body().string(), JsonObject.class));
					}
				}
				catch (Exception ignored)
				{
				}
			}
		});
	}

	/** Phase 3: Praeferenzen schreiben — Antwort enthaelt updatedAtMs (Server-Uhr). */
	public void putPreferences(String serverUrl, JsonObject prefs, Consumer<JsonObject> onSuccess)
	{
		JsonObject body = new JsonObject();
		body.add("prefs", prefs);
		Request request = authed(new Request.Builder())
			.url(serverUrl + "/me/preferences")
			.put(RequestBody.create(MediaType.parse("application/json"), body.toString()))
			.build();
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				try (Response r = response)
				{
					if (r.isSuccessful() && r.body() != null)
					{
						onSuccess.accept(gson.fromJson(r.body().string(), JsonObject.class));
					}
				}
				catch (Exception ignored)
				{
				}
			}
		});
	}

	/** Phase 4: Feedback/Bug-Report an den Server. */
	public void postFeedback(String serverUrl, String category, String message, JsonObject context,
		Consumer<Boolean> onDone)
	{
		JsonObject body = new JsonObject();
		body.addProperty("category", category);
		body.addProperty("message", message);
		body.add("context", context);
		Request request = authed(new Request.Builder())
			.url(serverUrl + "/feedback")
			.post(RequestBody.create(JSON, body.toString()))
			.build();
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				onDone.accept(false);
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				try (Response r = response)
				{
					onDone.accept(r.isSuccessful());
				}
			}
		});
	}

	/** M12a: leichter Dump-Alert-Poll (schnelle Zustellung, ohne den grossen Sync). */
	public void getDumpAlert(String serverUrl, int minProfit, long gp, Consumer<JsonObject> onSuccess)
	{
		Request request = authed(new Request.Builder())
			.url(serverUrl + "/dump/poll?minProfit=" + minProfit + "&gp=" + gp)
			.get()
			.build();
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				try (Response r = response)
				{
					if (r.isSuccessful() && r.body() != null)
					{
						onSuccess.accept(gson.fromJson(r.body().string(), JsonObject.class));
					}
				}
				catch (Exception ignored)
				{
				}
			}
		});
	}

	/** §4.5 Stats-Tab: aggregierte Flip-Statistik vom Server (sinceTs = Session-Beginn). */
	public void getStats(String serverUrl, long accountHash, long sinceTs, long itemsSince, long dayStart, Consumer<JsonObject> onSuccess, Consumer<String> onError)
	{
		Request request = authed(new Request.Builder())
			.url(serverUrl + "/me/stats?accountHash=" + accountHash + "&sinceTs=" + sinceTs + "&itemsSince=" + itemsSince + "&dayStart=" + dayStart)
			.get()
			.build();
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				onError.accept("Server nicht erreichbar");
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				try (Response r = response)
				{
					if (!r.isSuccessful() || r.body() == null)
					{
						onError.accept("Stats-Fehler " + r.code());
						return;
					}
					onSuccess.accept(gson.fromJson(r.body().string(), JsonObject.class));
				}
				catch (Exception e)
				{
					onError.accept("Stats unlesbar");
				}
			}
		});
	}

	public void postSuggestion(String serverUrl, JsonObject accountStatus, Consumer<JsonObject> onSuccess, Consumer<String> onError)
	{
		Request request = authed(new Request.Builder())
			.url(serverUrl + "/suggestion")
			.post(RequestBody.create(JSON, accountStatus.toString()))
			.build();

		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Server nicht erreichbar: {}", e.getMessage());
				onError.accept("Server nicht erreichbar");
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				try (Response r = response)
				{
					if (r.code() == 401)
					{
						onError.accept("AUTH_401"); // M9: Sync stoesst Token-Refresh an
						return;
					}
					if (!r.isSuccessful() || r.body() == null)
					{
						onError.accept("Server-Fehler HTTP " + r.code());
						return;
					}
					JsonObject body = gson.fromJson(r.body().string(), JsonObject.class);
					onSuccess.accept(body);
				}
				catch (Exception e)
				{
					log.warn("Antwort nicht lesbar", e);
					onError.accept("Antwort nicht lesbar");
				}
			}
		});
	}
}

package de.rsflipper;

import de.rsflipper.model.ClientSuggestion;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.FontID;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;

/**
 * Vorgeschlagenes Item in der GE-Suche (SPEC §4.4): Öffnet der User die Kauf-Suche,
 * erscheint das vorgeschlagene Item als klickbarer Eintrag ganz oben — kein Tippen
 * nötig. Der Klick löst das spielinterne Auswahl-Script aus (der User klickt selbst,
 * §1.5). Mechanik nach Marktanalyse (§16a): der "Previous search"-Bereich
 * der Suche (Kinder 0–3 von CHATBOX_GE_SEARCH_RESULTS) wird umgeschrieben bzw. erzeugt.
 */
@Slf4j
@Singleton
public class GeSearchSuggestion
{
	private static final int SELECT_SCRIPT = 754;
	private static final int SELECT_OP_ARG = 84;
	private static final int KEY_LISTENER_ARG = -2147483640;
	private static final int BRAND_GREEN = 0x10b981;  // Marken-Emerald (Website/Logo)
	private static final int BG_DARK = 0x0e1a15;      // dunkler Emerald-Grund
	private static final int HINT_GRAY = 0x9aa5a0;
	private static final int PINK = 0xff40d2;         // Dump-Alert (pink statt rot - rot = Abort, 2026-07-22)
	private static final int PINK_BG = 0x6e1f5c;      // pinker Zeilen-Grund im Blink-Hoch

	private final Client client;
	private final GameStateService gameState;
	private final RSFlipperConfig config;

	private int injectedItemId = -1;
	// Per-Frame-Pulsieren der Dump-Zeile (vom Overlay je Frame aufgerufen).
	private Widget pulseRect;
	private Widget pulseOutline;

	@Inject
	GeSearchSuggestion(Client client, GameStateService gameState, RSFlipperConfig config)
	{
		this.client = client;
		this.gameState = gameState;
		this.config = config;
	}

	/** Vom Plugin je GameTick aufgerufen (ClientThread). */
	public void tick()
	{
		if (config.passiveMode())
		{
			return;
		}
		Widget results = client.getWidget(ComponentID.CHATBOX_GE_SEARCH_RESULTS);
		if (results == null || results.isHidden())
		{
			injectedItemId = -1;
			return;
		}
		ClientSuggestion s = gameState.getCurrentSuggestion();
		if (s == null || !"buy".equals(s.getType()) || s.getItemId() <= 0)
		{
			return;
		}
		if (injectedItemId == s.getItemId())
		{
			return; // einmal injizieren; das Dump-Pulsieren laeuft per Frame ueber animate()
		}
		try
		{
			inject(results, s);
			injectedItemId = s.getItemId();
		}
		catch (Exception e)
		{
			log.debug("GE-Such-Vorschlag konnte nicht gesetzt werden", e);
		}
	}

	/** Per-Frame vom Overlay aufgerufen: pulsiert die rote Dump-Suchzeile glatt
	 *  (dieselbe Kosinus-Kurve wie der Slot). Opacity ist invertiert: 0 = deckend. */
	public void animate()
	{
		Widget rect = pulseRect;
		Widget outline = pulseOutline;
		if (rect == null || outline == null)
		{
			return;
		}
		ClientSuggestion s = gameState.getCurrentSuggestion();
		Widget results = client.getWidget(ComponentID.CHATBOX_GE_SEARCH_RESULTS);
		if (s == null || !s.isDumpAlert() || results == null || results.isHidden())
		{
			pulseRect = null;
			pulseOutline = null;
			return;
		}
		double t = (System.currentTimeMillis() % 900) / 900.0;
		float p = (float) (0.5 - 0.5 * Math.cos(2 * Math.PI * t)); // 0..1
		rect.setOpacity((int) (150 - 95 * p));    // 150 (dunkel) -> 55 (kraeftig)
		outline.setOpacity((int) (140 - 120 * p)); // 140 -> 20
		// KEIN revalidate() hier (Lag-Fund 2026-07-22): revalidate erzwingt eine
		// Layout-Neuberechnung des Chatbox-Baums — pro Frame x2 brach die Framerate ein,
		// sobald der Dump-Alert pulsierte. Opacity ist eine reine Render-Eigenschaft und
		// wird ohne revalidate uebernommen; Layout-Aenderungen macht nur inject().
	}

	private void inject(Widget results, ClientSuggestion s)
	{
		Widget[] children = results.getChildren();
		Widget rect;
		Widget label;
		Widget icon;
		Widget name;
		Widget hint;
		Widget outline;
		if (children != null && children.length >= 4
			&& children[0] != null && children[1] != null && children[2] != null && children[3] != null)
		{
			// Pfad 1: bestehenden "Previous search"-Block umschreiben.
			rect = children[0];
			label = children[1];
			name = children[2];
			icon = children[3];
		}
		else
		{
			// Pfad 2: kein Block vorhanden → selbst bauen.
			rect = results.createChild(-1, WidgetType.RECTANGLE);
			label = results.createChild(-1, WidgetType.TEXT);
			name = results.createChild(-1, WidgetType.TEXT);
			icon = results.createChild(-1, WidgetType.GRAPHIC);
		}
		// Zusatz-Kinder (Hinweis + Kontur) einmalig anlegen, danach wiederverwenden.
		children = results.getChildren();
		if (children != null && children.length >= 6 && children[4] != null && children[5] != null)
		{
			hint = children[4];
			outline = children[5];
		}
		else
		{
			hint = results.createChild(-1, WidgetType.TEXT);
			outline = results.createChild(-1, WidgetType.RECTANGLE);
		}

		int w = results.getWidth();

		// M12a Dump-Alert: rote Zeile statt Emerald-Look; die Farb-INTENSITAET pulsiert
		// per Frame ueber animate() (2026-07-19) — genau wie der Slot im Overlay.
		boolean dump = s.isDumpAlert();
		final int bgFill = dump ? PINK_BG : BG_DARK;
		int outlineColor = dump ? PINK : BRAND_GREEN;
		int labelColor = dump ? PINK : BRAND_GREEN;

		rect.setOriginalX(0);
		rect.setOriginalY(0);
		rect.setOriginalWidth(w);
		rect.setOriginalHeight(24);
		rect.setFilled(true);
		rect.setTextColor(bgFill);
		rect.setOpacity(dump ? 90 : 110);
		rect.setHasListener(true);
		rect.setAction(0, "Auswählen");
		rect.setOnOpListener(SELECT_SCRIPT, s.getItemId(), SELECT_OP_ARG);
		rect.setOnKeyListener(SELECT_SCRIPT, s.getItemId(), KEY_LISTENER_ARG);
		rect.setOnMouseOverListener((net.runelite.api.widgets.JavaScriptCallback) ev -> {
			rect.setTextColor(dump ? 0x8a2a78 : 0x123b2c);
			rect.setOpacity(70);
		});
		rect.setOnMouseLeaveListener((net.runelite.api.widgets.JavaScriptCallback) ev -> {
			rect.setTextColor(bgFill);
			rect.setOpacity(dump ? 90 : 110);
		});
		rect.revalidate();

		// Kontur um die Zeile (rot bei Dump, sonst Marken-Gruen).
		outline.setOriginalX(0);
		outline.setOriginalY(0);
		outline.setOriginalWidth(w);
		outline.setOriginalHeight(24);
		outline.setFilled(false);
		outline.setTextColor(outlineColor);
		outline.setOpacity(dump ? 80 : 90);
		outline.revalidate();

		// Referenzen fuers Per-Frame-Pulsieren merken (nur bei Dump aktiv).
		this.pulseRect = dump ? rect : null;
		this.pulseOutline = dump ? outline : null;

		label.setText(dump ? "DUMP" : "RS-Flipper");
		label.setFontId(FontID.BOLD_12);
		label.setTextColor(labelColor);
		label.setOriginalX(8);
		label.setOriginalY(5);
		label.setOriginalWidth(78);
		label.setOriginalHeight(15);
		label.revalidate();

		int hintW = 110;
		int hintX = w - 44 - hintW - 6;

		name.setText(s.getItemName() != null ? s.getItemName() : String.valueOf(s.getItemId()));
		name.setFontId(FontID.PLAIN_12);
		name.setTextColor(0xffffff);
		name.setOriginalX(90);
		name.setOriginalY(5);
		name.setOriginalWidth(Math.max(40, hintX - 94));
		name.setOriginalHeight(15);
		name.revalidate();

		// Hinweis: ENTER waehlt den Vorschlag direkt aus (Spiel-Listener, 2026-07-19).
		hint.setText("[ ENTER ]  select");
		hint.setFontId(FontID.PLAIN_11);
		hint.setTextColor(HINT_GRAY);
		hint.setOriginalX(hintX);
		hint.setOriginalY(6);
		hint.setOriginalWidth(hintW);
		hint.setOriginalHeight(14);
		hint.setXTextAlignment(2);
		hint.revalidate();

		icon.setItemId(s.getItemId());
		icon.setItemQuantity(1);
		icon.setItemQuantityMode(0);
		icon.setOriginalX(w - 44);
		icon.setOriginalY(0);
		icon.setOriginalWidth(36);
		icon.setOriginalHeight(24);
		icon.revalidate();

		log.debug("GE-Such-Vorschlag gesetzt: {} ({})", s.getItemName(), s.getItemId());
	}
}

package de.rsflipper;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(RSFlipperConfig.GROUP)
public interface RSFlipperConfig extends Config
{
	String GROUP = "rsflipper";

	enum Timeframe
	{
		M5("5 min", 5),
		M30("30 min", 30),
		H2("2 h", 120),
		H8("8 h", 480);

		private final String label;
		private final int minutes;

		Timeframe(String label, int minutes)
		{
			this.label = label;
			this.minutes = minutes;
		}

		public String label()
		{
			return label;
		}

		public int minutes()
		{
			return minutes;
		}
	}

	/**
	 * Risikostufe (31.08.). Bis dahin lief jeder still auf "aggressiv" — das war
	 * ein Vorgabewert, keine Entscheidung. Gemessen im kalibrierten Backtest (50M, 5 Tage):
	 *   CAREFUL     Groesstverlust -210k | Verlust/Gewinn 18,2 % | 40.419 gp/h
	 *   BALANCED    Groesstverlust -354k | Verlust/Gewinn 25,5 % | 65.604 gp/h
	 *   AGGRESSIVE  hoechster Ertrag, dafuer auch mal ein dicker Verlust
	 * Wichtig fuer die Erwartungshaltung: CAREFUL heisst kleine, planbare Verluste —
	 * NICHT "keine Verluste". Die Win-Rate liegt dort sogar leicht niedriger.
	 */
	enum RiskLevel
	{
		CAREFUL("vorsichtig"),
		BALANCED("ausgewogen"),
		AGGRESSIVE("aggressiv");

		private final String wire;

		RiskLevel(String wire)
		{
			this.wire = wire;
		}

		public String wire()
		{
			return wire;
		}
	}

	/**
	 * Risikostufe - AUSGEBLENDET seit 09.09.2026, weil sie die Vorschlaege nicht mehr
	 * steuert. Schluessel und Enum bleiben stehen: So gehen bestehende Einstellungen
	 * nicht verloren und die Auswahl kann zurueckkehren, wenn die Stufen sich messbar
	 * bewaehren.
	 */
	@ConfigItem(
		keyName = "riskLevel",
		name = "Risk level",
		description = "Currently not used - all users get the same suggestion logic",
		hidden = true
	)
	default RiskLevel riskLevel()
	{
		return RiskLevel.BALANCED;
	}

	@ConfigItem(keyName = "serverUrl", name = "Server URL", description = "Address of the RS-Flipper server", position = 0)
	default String serverUrl()
	{
		// Live-API seit 2026-07-19 (M8-Go-Live) — Dev: auf http://localhost:8080 umstellen.
		return "https://api.rs-flipper.com";
	}

	@ConfigItem(keyName = "useP2p", name = "Use P2P suggestions (free tier)", description = "Spend your 10 free members-item suggestions per day; unchecked = F2P suggestions only", hidden = true)
	default boolean useP2p()
	{
		return false;
	}

	// M12a Dump-Alerts (2026-07-19): Schwelle in gp, 0 = Feature aus (bewusst Opt-in).
	@ConfigItem(keyName = "dumpMinProfit", name = "Dump alert min profit", description = "Minimum predicted profit for dump alerts; 0 = off", hidden = true)
	default int dumpMinProfit()
	{
		return 0;
	}


	@ConfigItem(keyName = "dumpSound", name = "Dump alert sound", description = "Play the GE offer sound when a dump alert arrives", hidden = true)
	default boolean dumpSound()
	{
		return true;
	}

	// Phase 3 (2026-07-20): Sync an/aus ist bewusst LOKAL je Client — aus =
	// dieser Client behaelt eigene Werte (zwei Chars, zwei Setups).
	@ConfigItem(keyName = "syncSettings", name = "Sync settings across devices", description = "Keep timeframe, min profit, blocklist and dump settings in sync via your account", hidden = true)
	default boolean syncSettings()
	{
		return true;
	}

	/**
	 * Gesperrte Slots (1-basiert, z. B. "7,8"). Nur noch Speicher: Bedient wird die
	 * Sperre seit 01.09.2026 ueber das Vorhaengeschloss am leeren Slot selbst -
	 * das Textfeld im Dialog war dafuer der falsche Ort.
	 */
	@ConfigItem(
		keyName = "ignoredSlots",
		name = "Ignored GE slots",
		description = "Managed with the padlock on each empty GE slot",
		hidden = true
	)
	default String ignoredSlots()
	{
		return "";
	}

	@ConfigItem(keyName = "targetEtf", name = "Preferred fill time",
		description = "Suggestions aim for this speed. Much faster flips are filtered out unless nothing else is available.",
		position = 2)
	default Timeframe targetEtf()
	{
		// Voreinstellung 5 min (2026-07-19): neue User (= Free) starten mit dem
		// schnellsten Fenster — laengere Fenster laufen im Free-Tier schnell leer.
		return Timeframe.M5;
	}

	@ConfigItem(keyName = "minProfitGp", name = "Minimum profit (gp)", description = "Hard floor: only flips promising at least this profit are suggested (0 = off)", position = 3)
	default int minProfitGp()
	{
		// Voreinstellung 5k (2026-07-19) — realistisch fuers Free-Tier.
		return 5000;
	}

	@ConfigItem(keyName = "blockedItems", name = "Blocked items", description = "Item IDs, comma-separated - never suggested", position = 3)
	default String blockedItems()
	{
		return "";
	}

	@ConfigItem(keyName = "highlightColor", name = "Highlight color", description = "Color of the GE slot highlight", position = 4)
	default Color highlightColor()
	{
		return new Color(255, 152, 31);
	}

	@ConfigItem(keyName = "fillHotkey", name = "Apply", description = "Key that applies the suggested value (quantity/price) to the open GE input - 1 keypress = 1 action", position = 5)
	default net.runelite.client.config.Keybind fillHotkey()
	{
		// Standard: ENTER (2026-07-19) — 2x Enter = uebernehmen + bestaetigen.
		// '#' funktioniert zusaetzlich fest verdrahtet; umbelegbar bleibt der Keybind.
		return new net.runelite.client.config.Keybind(java.awt.event.KeyEvent.VK_ENTER, 0);
	}

	@ConfigItem(keyName = "skipHotkey", name = "Skip hotkey", description = "Key that skips the current suggestion (item paused for 10 min)", position = 6)
	default net.runelite.client.config.Keybind skipHotkey()
	{
		// Standard: + (VK_PLUS, deutsche Tastatur) — umbelegbar.
		return new net.runelite.client.config.Keybind(java.awt.event.KeyEvent.VK_PLUS, 0);
	}

	@ConfigItem(keyName = "chartHotkey", name = "Chart hotkey", description = "Key that opens the suggested item's price chart on rs-flipper.com (only while the GE is open)", position = 7)
	default net.runelite.client.config.Keybind chartHotkey()
	{
		// Standard: '-' (2026-07-22) — wirkt nur bei offener GE, tippt dort nie in den Chat.
		return new net.runelite.client.config.Keybind(java.awt.event.KeyEvent.VK_MINUS, 0);
	}

	@ConfigItem(keyName = "passiveMode", name = "Passive mode (observe only)", description = "Plugin keeps syncing with the server (suggestion logging) but never touches the game (no highlights, hotkey fills, GE search entry or slot action swap). For running alongside other flipping plugins.", position = 8)
	default boolean passiveMode()
	{
		return false;
	}

	@ConfigItem(keyName = "slotActionSwap", name = "Slot left-click = action", description = "When abort/modify is suggested, that action becomes the default left-click on the GE slot", position = 7)
	default boolean slotActionSwap()
	{
		return true;
	}

	@ConfigItem(keyName = "geSlotChildBase", name = "GE slot widget base", description = "First slot child in the GE interface (calibration, default 7)", position = 90)
	default int geSlotChildBase()
	{
		return 7;
	}
}

package de.rsflipper;

import java.awt.Rectangle;
import java.awt.event.MouseEvent;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.input.MouseAdapter;

/**
 * Slot-Sperre per Vorhaengeschloss am leeren GE-Slot (01.09.2026, ersetzt das
 * CSV-Feld "Ignored GE slots" aus dem Konfigurationsdialog).
 *
 * Der Zustand liegt weiter in der Konfiguration ({@code ignoredSlots}, 1-basiert wie
 * im Spiel) — nur die Bedienung wandert an den Slot selbst. Damit bleiben bestehende
 * Einstellungen gueltig und die Sperre ueberlebt einen Client-Neustart.
 *
 * Klick-Behandlung bewusst OHNE Client-Zugriff: Die Trefferflaechen setzt das Overlay
 * pro Bild im Client-Thread, hier wird nur noch Geometrie verglichen. Ein Klick auf das
 * Schloss wird verbraucht, damit er nicht zusaetzlich das Kauf-Fenster des Slots oeffnet.
 */
@Singleton
public class SlotLocks extends MouseAdapter
{
	private final RSFlipperConfig config;
	private final ConfigManager configManager;

	/** Trefferflaeche des Schlosses je Slot (0-basiert) — pro Bild vom Overlay gepflegt. */
	private final Map<Integer, Rectangle> hitBoxes = new ConcurrentHashMap<>();

	/** Zuletzt geparster Konfigurationswert samt Ergebnis. */
	private volatile String rohStand = null;
	private volatile Set<Integer> geparst = Collections.emptySet();

	/** Wird nach einer Aenderung gerufen, damit der naechste Sync sofort geht. */
	private volatile Runnable onChanged;

	@Inject
	SlotLocks(RSFlipperConfig config, ConfigManager configManager)
	{
		this.config = config;
		this.configManager = configManager;
	}

	public void setOnChanged(Runnable r)
	{
		this.onChanged = r;
	}

	/**
	 * Gesperrte Slots, 0-basiert. Gepuffert, weil die Abfrage mehrfach je Bild
	 * laeuft (Overlay, Slot-Vorschlag, Sync) - neu geparst wird nur nach einer
	 * Aenderung.
	 */
	public Set<Integer> locked()
	{
		String roh = config.ignoredSlots();
		String schluessel = roh == null ? "" : roh;
		if (!schluessel.equals(rohStand))
		{
			geparst = parse(schluessel);
			rohStand = schluessel;
		}
		return geparst;
	}

	/** Trefferflaeche eines Schlosses melden (Overlay, je Bild). */
	public void setHitBox(int slot, Rectangle r)
	{
		hitBoxes.put(slot, r);
	}

	public void clearHitBox(int slot)
	{
		hitBoxes.remove(slot);
	}

	public void clearHitBoxes()
	{
		hitBoxes.clear();
	}

	@Override
	public MouseEvent mousePressed(MouseEvent e)
	{
		if (!SwingUtilities.isLeftMouseButton(e))
		{
			return e;
		}
		for (Map.Entry<Integer, Rectangle> entry : hitBoxes.entrySet())
		{
			if (entry.getValue().contains(e.getPoint()))
			{
				toggle(entry.getKey());
				e.consume();
				return e;
			}
		}
		return e;
	}

	/**
	 * Auch Loslassen und Klick verbrauchen, solange der Zeiger auf dem Schloss steht.
	 * Der Client wertet beide Ereignisse aus; ohne das oeffnete der Klick trotz
	 * verbrauchtem mousePressed noch das Kauf-Fenster des Slots.
	 */
	@Override
	public MouseEvent mouseReleased(MouseEvent e)
	{
		return verbrauchenWennAufSchloss(e);
	}

	@Override
	public MouseEvent mouseClicked(MouseEvent e)
	{
		return verbrauchenWennAufSchloss(e);
	}

	private MouseEvent verbrauchenWennAufSchloss(MouseEvent e)
	{
		if (!SwingUtilities.isLeftMouseButton(e))
		{
			return e;
		}
		for (Rectangle r : hitBoxes.values())
		{
			if (r.contains(e.getPoint()))
			{
				e.consume();
				return e;
			}
		}
		return e;
	}

	private void toggle(int slot)
	{
		Set<Integer> aktuell = new LinkedHashSet<>(locked());
		if (!aktuell.remove(slot))
		{
			aktuell.add(slot);
		}
		StringBuilder sb = new StringBuilder();
		for (int s : aktuell)
		{
			if (sb.length() > 0)
			{
				sb.append(',');
			}
			sb.append(s + 1); // in der Konfiguration 1-basiert, wie die Slots im Spiel
		}
		configManager.setConfiguration(RSFlipperConfig.GROUP, "ignoredSlots", sb.toString());
		Runnable r = onChanged;
		if (r != null)
		{
			r.run();
		}
	}

	/** "7,8" -> {6,7}. Unlesbares wird still verworfen. */
	static Set<Integer> parse(String csv)
	{
		if (csv == null || csv.trim().isEmpty())
		{
			return Collections.emptySet();
		}
		Set<Integer> out = new LinkedHashSet<>();
		for (String part : csv.split(","))
		{
			try
			{
				int n = Integer.parseInt(part.trim());
				if (n >= 1 && n <= 8)
				{
					out.add(n - 1);
				}
			}
			catch (NumberFormatException ignored)
			{
				// Handeingetragener Unsinn darf die Sperre nicht kippen.
			}
		}
		return out;
	}
}
